-- Run in the existing Supabase project's SQL Editor. Additive and safe to rerun.
create table if not exists public.users (
  id text primary key, email text not null unique, display_name text not null, avatar_url text,
  timezone text not null default 'Asia/Taipei', last_login_at timestamptz not null default now(),
  created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
create table if not exists public.checkins (
  id bigint generated by default as identity primary key, user_id text not null references public.users(id) on delete cascade,
  owner_email text not null, entry_date text not null, metrics text not null, sleep integer not null default 0,
  stress integer not null default 0, note text not null default '', whole_routine text not null default '',
  left_routine text not null default '', right_routine text not null default '', created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(), unique (user_id, entry_date)
);
create table if not exists public.face_photos (
  id bigint generated by default as identity primary key, user_id text not null references public.users(id) on delete cascade,
  owner_email text not null, entry_date text not null, angle text not null check (angle in ('front','left','right')),
  object_key text not null unique, content_type text not null, created_at timestamptz not null default now()
);
create table if not exists public.tracking_projects (
  id text primary key, user_id text not null references public.users(id) on delete cascade, name text not null,
  description text not null default '', enable_face_angle_guidance boolean not null default false,
  created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
create table if not exists public.project_photos (
  id bigint generated by default as identity primary key, user_id text not null references public.users(id) on delete cascade,
  project_id text not null references public.tracking_projects(id) on delete cascade, storage_key text not null unique,
  content_type text not null, captured_date text not null, captured_time text, captured_at timestamptz,
  capture_time_known boolean not null default true, capture_time_source text not null default 'manual',
  uploaded_at timestamptz not null default now(), photo_source text not null check (photo_source in ('camera','album','historical_import')),
  note text not null default '', created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
create index if not exists tracking_projects_user_idx on public.tracking_projects(user_id);
create index if not exists project_photos_user_capture_idx on public.project_photos(user_id,captured_date,captured_time);
create index if not exists project_photos_project_capture_idx on public.project_photos(project_id,captured_date,captured_time);

insert into public.tracking_projects (id,user_id,name,description,enable_face_angle_guidance)
select 'legacy-face-'||id,id,'臉部肌膚追蹤','由既有臉部照片自動建立',true from public.users on conflict (id) do nothing;
insert into public.project_photos (user_id,project_id,storage_key,content_type,captured_date,captured_time,captured_at,
  capture_time_known,capture_time_source,uploaded_at,photo_source,note,created_at,updated_at)
select user_id,'legacy-face-'||user_id,object_key,content_type,entry_date,null,created_at,false,'legacy_created_at_fallback',
  created_at,'historical_import','',created_at,created_at from public.face_photos where user_id is not null
on conflict (storage_key) do nothing;

alter table public.users enable row level security;
alter table public.checkins enable row level security;
alter table public.face_photos enable row level security;
alter table public.tracking_projects enable row level security;
alter table public.project_photos enable row level security;

drop policy if exists users_select_own on public.users; drop policy if exists users_insert_own on public.users; drop policy if exists users_update_own on public.users;
create policy users_select_own on public.users for select using (auth.uid()::text=id);
create policy users_insert_own on public.users for insert with check (auth.uid()::text=id);
create policy users_update_own on public.users for update using (auth.uid()::text=id) with check (auth.uid()::text=id);
drop policy if exists checkins_select_own on public.checkins; drop policy if exists checkins_insert_own on public.checkins; drop policy if exists checkins_update_own on public.checkins; drop policy if exists checkins_delete_own on public.checkins;
create policy checkins_select_own on public.checkins for select using (auth.uid()::text=user_id);
create policy checkins_insert_own on public.checkins for insert with check (auth.uid()::text=user_id);
create policy checkins_update_own on public.checkins for update using (auth.uid()::text=user_id) with check (auth.uid()::text=user_id);
create policy checkins_delete_own on public.checkins for delete using (auth.uid()::text=user_id);
drop policy if exists photos_select_own on public.face_photos; drop policy if exists photos_insert_own on public.face_photos; drop policy if exists photos_delete_own on public.face_photos;
create policy photos_select_own on public.face_photos for select using (auth.uid()::text=user_id);
create policy photos_insert_own on public.face_photos for insert with check (auth.uid()::text=user_id);
create policy photos_delete_own on public.face_photos for delete using (auth.uid()::text=user_id);
drop policy if exists tracking_projects_select_own on public.tracking_projects; drop policy if exists tracking_projects_insert_own on public.tracking_projects; drop policy if exists tracking_projects_update_own on public.tracking_projects; drop policy if exists tracking_projects_delete_own on public.tracking_projects;
create policy tracking_projects_select_own on public.tracking_projects for select using (auth.uid()::text=user_id);
create policy tracking_projects_insert_own on public.tracking_projects for insert with check (auth.uid()::text=user_id);
create policy tracking_projects_update_own on public.tracking_projects for update using (auth.uid()::text=user_id) with check (auth.uid()::text=user_id);
create policy tracking_projects_delete_own on public.tracking_projects for delete using (auth.uid()::text=user_id);
drop policy if exists project_photos_select_own on public.project_photos; drop policy if exists project_photos_insert_own on public.project_photos; drop policy if exists project_photos_update_own on public.project_photos; drop policy if exists project_photos_delete_own on public.project_photos;
create policy project_photos_select_own on public.project_photos for select using (auth.uid()::text=user_id);
create policy project_photos_insert_own on public.project_photos for insert with check (auth.uid()::text=user_id and exists (select 1 from public.tracking_projects p where p.id=project_id and p.user_id=auth.uid()::text));
create policy project_photos_update_own on public.project_photos for update using (auth.uid()::text=user_id) with check (auth.uid()::text=user_id);
create policy project_photos_delete_own on public.project_photos for delete using (auth.uid()::text=user_id);

insert into storage.buckets (id,name,public,file_size_limit,allowed_mime_types)
values ('face-photos','face-photos',false,4194304,array['image/jpeg','image/png','image/webp'])
on conflict (id) do update set public=false,file_size_limit=4194304,allowed_mime_types=excluded.allowed_mime_types;
drop policy if exists storage_select_own_photos on storage.objects; drop policy if exists storage_insert_own_photos on storage.objects; drop policy if exists storage_delete_own_photos on storage.objects;
create policy storage_select_own_photos on storage.objects for select using (bucket_id='face-photos' and (storage.foldername(name))[1]=auth.uid()::text);
create policy storage_insert_own_photos on storage.objects for insert with check (bucket_id='face-photos' and (storage.foldername(name))[1]=auth.uid()::text);
create policy storage_delete_own_photos on storage.objects for delete using (bucket_id='face-photos' and (storage.foldername(name))[1]=auth.uid()::text);
